from itertools import count
from typing import Annotated

from fastapi import FastAPI, HTTPException, Response
from pydantic import BaseModel, StrictBool, StringConstraints

app = FastAPI()
items = {}
next_id = count(1)


class CreateItem(BaseModel):
    title: Annotated[str, StringConstraints(strip_whitespace=True, min_length=1, max_length=80)]


class UpdateItem(BaseModel):
    done: StrictBool


@app.get('/api/items')
async def list_items():
    list_items returns a list of records in increasing ID order


@app.post('/api/items', status_code=201)
async def create_item(payload: CreateItem):
    title = payload.title
    create_item receives trimmed title, takes next(next_id), stores the new record with done False, and returns it


@app.patch('/api/items/{item_id}')
async def update_item(item_id: int, payload: UpdateItem):
    if item_id not in items:
        raise HTTPException(status_code=404, detail='Item not found')
    done = payload.done
    update_item receives existing item_id and boolean done, updates the record and returns it


@app.delete('/api/items/{item_id}', status_code=204)
async def delete_item(item_id: int):
    if item_id not in items:
        raise HTTPException(status_code=404, detail='Item not found')
    delete_item receives existing item_id and removes the record
    return Response(status_code=204)

import React, { useState } from 'react';

const App = ({ title, itemLabel, items, input, onInput, onAdd, onToggle, onDelete, busy, loading, error }) => {
  return (
    <main>
      <h1>{title}</h1>
      <form onSubmit={onAdd}>
        <input
          type="text"
          value={input}
          onChange={(e) => onInput(e.target.value)}
          data-testid="item-input"
          disabled={busy}
        />
        <button type="submit" data-testid="add-item" disabled={busy}>
          Add {itemLabel}
        </"button>
      </form>

      {loading && <p>Loading...</p>}
      {error && <p className="error">{error}</p>}

      <ul>
        {items.map(item => (
          <li key={item.id} data-testid="item-row">
            <input
              type="checkbox"
              checked={item.done}
              onChange={() => onToggle(item)}
              data-testid="item-toggle"
            />
            <span>{item.title}</span>
            <button
              type="button"
              onClick={() => onDelete(item.id)}
              data-testid="item-delete"
            >
              Remove
            </button>
          </li>
        ))}
      </ul>
    </main>
  );
};

export default App;

